    { ?item wdt:P131* ?city . BIND("administrative-path" AS ?evidenceType) }
    UNION { ?item wdt:P276 ?city . BIND("direct-location" AS ?evidenceType) }
    UNION { ?item wdt:P17 ?country . BIND("country-match" AS ?evidenceType) }
  }
